  "loc.enterInternetConnectionsAddress": "Enter your internet connection's address as the server (e.g. your MyFRITZ! address) – usually by SMS command according to the tracker's manual.",
  "loc.enterShopAddressesUnder": "You enter shop addresses under Lists → Edit shopping list – if a shop exists more than once, several branches too. If someone stays there for a while, the planned shopping trip is checked off.",
  "loc.familyDoesntSeeYou": "Your family can’t see you on the map right now.",
