  "loc.fields": "Fields: {felder}",
  "loc.fromPinn": "from pinn.",
  "loc.fromTraccar": "from “Traccar Client”",
  "loc.gettingLocation": "Getting location …",
  "loc.gpsTracker": "🛰️ GPS tracker",
  "loc.guide1": "Install the app <b>“Traccar Client”</b> (App Store or Google Play, free).",
  "loc.guide2": "In the app, enter under <b>Device ID</b> (Device identifier):",
  "loc.guide3": "Enter under <b>Server URL</b>:",
  "loc.guide4": "Accuracy <b>Medium</b>, distance <b>50 m</b>. The app then only sends when you move – nothing while standing still. If you have more fields (interval, heartbeat), set heartbeat off or 0.",
  "loc.guide5": "Allow location access: <b>Always</b> and <b>Precise Location</b> on.",
  "loc.guide6": "Turn on the <b>Service / Tracking</b> switch and <b>always leave it on</b> – done. From now on you control everything in pinn.: “Send permanently” on or off, “Send once” and SOS. As long as “Send permanently” is off, nobody sees your location and pinn. records no route.",
  "loc.guideIntro": "Without another app, “📍 Share location” works directly in pinn. – but only while pinn. is open. So that the location also arrives when pinn. is closed and the screen is locked, the free app “Traccar Client” sends it directly to pinn. (no Traccar server needed). The same for iPhone and Android.",
  "loc.h025013Watch5093": ", H02 5013, Watch 5093, Teltonika 5027. This port must be forwarded to the NAS in the FRITZ!Box, because the tracker connects from the mobile network.",
  "loc.haveGoodTripFamily": "Have a good trip! The family has been informed.",
  "loc.haveGoodTripFamily#wg": "Have a good trip! The flatshare has been informed.",
  "loc.home": "· Home",
  "loc.howLong": "How long?",
  "loc.idRandomLinksPhone": "The ID is random – it links the phone to this person.",
  "loc.ifSomeoneArrivesLeaves": "If someone arrives at or leaves a place, there is a push notification. “Home” also ends “I'm on my way”.",
  "loc.ifTrackerHasSos": "If the tracker has an SOS button, pinn. alerts the whole family by push (within a minute) as soon as Traccar detects the tracker's alarm.",
  "loc.ifTrackerHasSos#wg": "If the tracker has an SOS button, pinn. alerts the whole flatshare by push (within a minute) as soon as Traccar detects the tracker's alarm.",
  "loc.imeiTrackerPackagingComes": "The IMEI is on the tracker, the packaging or comes via SMS command.",
  "loc.insertSimCardMobile": "Insert a SIM card with mobile data and switch the tracker on.",
  "loc.instructions": "Instructions",
