  "loc.setupIntro": "Phones need nothing else: everyone can share directly in pinn. under “My location”. In the background (pinn. closed) the phone sends with the free app “Traccar Client” (iPhone and Android) – directly to pinn., no Traccar server is needed. Only GPS trackers with a SIM card (e.g. on a collar) need the “traccar” container. The locations stay on your NAS.",
  "loc.setupTrackersUnder": "You set up GPS trackers and the background app under {btn}.",
  "loc.shareAlreadyEnded": "Your sharing has already ended.",
  "loc.shareIntro": "Your family sees you live on the map. It only sends when you move – nothing while standing still. When pinn. is closed, the “Traccar Client” app you set up once sends.",
  "loc.shareIntro#wg": "Your flatshare sees you live on the map. It only sends when you move – nothing while standing still. When pinn. is closed, the “Traccar Client” app you set up once sends.",
  "loc.sharedUntil": "shared {until}",
  "loc.sharingNotPossible": "Sharing not possible",
  "loc.sharingOff": "Sharing off",
  "loc.shopSaved": "Shop saved",
  "loc.shops": "🛒 Shops",
  "loc.showsWhatTraccarClient": "Shows what “Traccar Client” sends to pinn. After pressing SOS, “🆘 detected” must appear here.",
  "loc.simContainer": "SIM card · “traccar” container",
  "loc.sosAlwaysPush": "In an emergency (SOS) the family always gets a push message.",
  "loc.sosAlwaysPush#wg": "In an emergency (SOS) the flatshare always gets a push message.",
  "loc.sosDetected": "🆘 detected",
  "loc.sosTestCreatedPush": "SOS test created – push is not activated on this profile",
  "loc.sosTestMe": "🆘 SOS test to me",
  "loc.sosTestNotPossible": "SOS test not possible",
  "loc.sosTestSent": "SOS test sent",
  "loc.startSending": "Start sending",
  "loc.streetTown": "Street, town",
  "loc.testSameProcessReal": "Test: same process as a real call for help (push, popup, map, address) – but only to you, the family doesn't notice anything.",
  "loc.testSameProcessReal#wg": "Test: same process as a real call for help (push, popup, map, address) – but only to you, the flatshare doesn't notice anything.",
  "loc.tipSetAddressUnder": "Tip: Set your address under Settings → Home – then the place “Home” exists automatically, with push on arrival and departure.",
  "loc.traccarClientChooseSend": "In “Traccar Client”, choose “Send SOS” (depending on the version in the app or by long-pressing the app icon). pinn. immediately alerts all family members by push – with location, address, time and buttons for call and emergency {regionNotrufText}. Tip: enter your own mobile number in the emergency card.",
  "loc.traccarClientChooseSend#wg": "In “Traccar Client”, choose “Send SOS” (depending on the version in the app or by long-pressing the app icon). pinn. immediately alerts all flatmates by push – with location, address, time and buttons for call and emergency {regionNotrufText}. Tip: enter your own mobile number in the emergency card.",
  "loc.traccarSetUpShownWhen": "“Traccar Client” is set up – you are only shown once you send permanently.",
  "loc.trackerPorts": "GPS trackers (only with the “traccar” container): address of your internet connection and port per protocol – GT06 5023 · H02 5013 · Watch 5093 · Teltonika 5027 (device ID = IMEI).",
  "loc.trackerViaSim": "The tracker sends via its SIM card directly to Traccar on your NAS – for this the “traccar” container must be running (phones don’t need it).",
  "loc.trackersNeedContainer": "GPS trackers need the “traccar” container.",
  "loc.unknown": "unknown",
