  "settings.calendar.info": "Each profile signs in with its own iCloud or Google account and ticks the calendars from it: “For me” is only seen by your own profile, “Family” is seen and used by everyone in your family. The others only see which account a family calendar comes from – obscured, e.g. m**l@g***l.com. Events can be created, edited, moved and queued offline as usual and go directly to iCloud or Google (and thus to the phone). Sync every 15 minutes or with “Update now”. Without an account, a calendar on your pinn. server only also works. Reminders and daily summary by push: private events only to you.",
  "settings.calendar.info#wg": "Each profile signs in with its own iCloud or Google account and ticks the calendars from it: “For me” is only seen by your own profile, “Flatshare” is seen and used by everyone in your flatshare. The others only see which account a flatshare calendar comes from – obscured, e.g. m**l@g***l.com. Events can be created, edited, moved and queued offline as usual and go directly to iCloud or Google (and thus to the phone). Sync every 15 minutes or with “Update now”. Without an account, a calendar on your pinn. server only also works. Reminders and daily summary by push: private events only to you.",
