  "smart.actionsHint": "Name of the action as it appears on the task, next to it the approximate duration in minutes. With a duration, the device is occupied for that long – further actions of the same device only start afterwards (e.g. first vacuum the living room, then mop the kitchen). Better plan a few minutes of buffer, including the return trip to the station. With Home Assistant and a status entity, the device's real state also counts.",
