  "smart.guide1": "1. New shortcut “pinn Automatik”:",
  "smart.guide10": "The device must reach pinn. for this (Wi-Fi at home or VPN). Each action runs only once per task; anything already started by button is not started again by the automation.",
  "smart.guide2": "• “Get Contents of URL” – paste the link above",
  "smart.guide3": "• “Get Dictionary Value” – key “aktionen”",
  "smart.guide4": "• “Repeat with Each”, inside:",
  "smart.guide5": "– “Get Dictionary Value” – key “eingabe” from “Repeat Item”",
  "smart.guide6": "– “Get Dictionary Value” – key “kurzbefehl” from “Repeat Item”",
  "smart.guide7": "– “Run Shortcut” – choose the value “kurzbefehl” as shortcut and the value “eingabe” as input",
  "smart.guide8": "2. Tab “Automation” → “Time of Day” – one automation per time at the top, “Run Immediately” → “pinn Automatik”.",
  "smart.guide9": "3. Tip: additionally “Arrive” (Home) → “pinn Automatik” – catches up on anything missed.",
