  "smart.haTip1": "Roborock: create the device “Robot vacuum”, choose the robot (vacuum.…) above – pinn. loads the rooms from the map. Per action “Room cleaning” with rooms and mode (vacuum, vacuum & mop, mop). “Room of the task” uses the room of the household cleaning task – the names must be the same as in the Roborock app.",
